const Hapi = require('@hapi/hapi');
const { AppDataSource } = require('../data-source');
const { TicketAttachment } = require('../entities/TicketAttachment');
const { SupportTicket } = require('../entities/SupportTicket');

const server = Hapi.server({ port: 5005 });

server.ext('onPreHandler', (request, h) => {
  if (!request.auth.credentials || request.auth.credentials.role !== 'support_client') {
    return h.response({ error: 'Unauthorized role' }).code(403).takeover();
  }
  return h.continue;
});

server.route({
  method: 'GET',
  path: '/support/tickets/{ticketId}/attachments/{attachmentId}',
  options: { auth: 'session' },
  handler: async (request, h) => {
    const { ticketId, attachmentId } = request.params;
    const customerId = request.auth.credentials.customerId;

    const ticketRepo = AppDataSource.getRepository(SupportTicket);
    const ticket = await ticketRepo.findOne({
      where: { id: ticketId, customerId }
    });

    if (!ticket) {
      return h.response({ error: 'Ticket not found or unauthorized' }).code(404);
    }

    const attachmentRepo = AppDataSource.getRepository(TicketAttachment);
    const attachment = await attachmentRepo.findOne({
      where: { id: attachmentId, ticketId }
    });

    if (!attachment) {
      return h.response({ error: 'Attachment not found for this ticket' }).code(404);
    }

    return h.response({
      id: attachment.id,
      fileName: attachment.fileName,
      mimeType: attachment.mimeType,
      downloadUrl: attachment.publicCdnUrl
    }).code(200);
  }
});
